def classify_features(fv):
    x = [fv.get(k, 0.0) for k in FEATURES]
    node = 0
    while True:
        f = _FEAT[node]
        if f == -2:
            probs = _VAL[node][0]
            s = sum(probs)
            idx = max(range(len(probs)), key=probs.__getitem__)
            return CLASSES[idx], (probs[idx]/s if s else 0.0)
        node = _LEFT[node] if x[f] <= _THRESH[node] else _RIGHT[node]

